-- Playbooks (S1: data, validated by the engine before it runs). mode on: the engine holds each row in measure for breach_doctor_playbook_cooldown_min (30) and demotes it after 2 failed cases in 24 h.
INSERT OR IGNORE INTO breach_playbooks (rule_id, version, family, cause_class, action_kind, trigger_sql, action_sql, revert_sql, verify_sql, min_ladder, max_per_tick, max_per_day, enabled, mode, note) VALUES
 ('MD-1', 1, 'METRIC-TRIGGER', 'metric-duplicate', 'sql', 'WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid, COALESCE((SELECT CASE WHEN lower(trim(substr(a.title, instr(a.title, '': '') + 2))) = lower(trim(substr(COALESCE(NULLIF(t0.title, ''''), NULLIF(t0.action, ''''), ''''), 1, 80))) THEN 0 ELSE 1 END FROM analytics_metric_triggers t0 WHERE t0.id = CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER)), 1) AS cur FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'' AND COALESCE(a.source, '''') NOT LIKE ''owner%''), d AS (SELECT tid, COUNT(*) AS n, MIN(cur * 4000000000 + (CASE pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + issue_id) AS keep_key FROM oi WHERE tid IS NOT NULL AND tid > 0 GROUP BY tid HAVING COUNT(*) > 1) SELECT oi.issue_id AS issue_id, ''duplicate-trigger-issue'' AS subject, json_object(''trigger_id'', oi.tid, ''survivor_issue'', d.keep_key % 1000000000, ''open_issues'', d.n) AS facts_json FROM oi JOIN d ON d.tid = oi.tid WHERE oi.cur * 4000000000 + (CASE oi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + oi.issue_id <> d.keep_key AND (d.keep_key % 4000000000) / 1000000000 <= (CASE oi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = oi.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host''))', json_array('WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid, COALESCE((SELECT CASE WHEN lower(trim(substr(a.title, instr(a.title, '': '') + 2))) = lower(trim(substr(COALESCE(NULLIF(t0.title, ''''), NULLIF(t0.action, ''''), ''''), 1, 80))) THEN 0 ELSE 1 END FROM analytics_metric_triggers t0 WHERE t0.id = CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER)), 1) AS cur FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'' AND COALESCE(a.source, '''') NOT LIKE ''owner%''), d AS (SELECT tid, COUNT(*) AS n, MIN(cur * 4000000000 + (CASE pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + issue_id) AS keep_key FROM oi WHERE tid IS NOT NULL AND tid > 0 GROUP BY tid HAVING COUNT(*) > 1) INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT oi.issue_id, ''breach-doctor:MD-1'', ''closed'', ''breach-doctor'', datetime(''now''), ''SUPERSEDED BY #'' || (d.keep_key % 1000000000) || '': both issues are open for metric trigger '' || oi.tid || '' (a trigger whose title was edited files a second issue because the dedupe key is the whole title), and #'' || (d.keep_key % 1000000000) || '' carries the work: its title is the one evaluateMetricTriggers looks up for the trigger now (when neither title is, it has the higher priority or the lower id) and it is at least as urgent. Closed by breach-doctor rule MD-1 from agent_issues and analytics_metric_triggers facts only.'' FROM oi JOIN d ON d.tid = oi.tid WHERE oi.cur * 4000000000 + (CASE oi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + oi.issue_id <> d.keep_key AND (d.keep_key % 4000000000) / 1000000000 <= (CASE oi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = oi.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = oi.issue_id OR xw.path = ''issue:'' || oi.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND oi.issue_id = ?1 ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = ''closed'', owner = ''breach-doctor'', close_evidence = excluded.close_evidence'), json_array('UPDATE issue_triage SET triage_state = ''triaged'', close_evidence = NULL WHERE issue_id = ?1', 'UPDATE agent_issues SET status = ''open'', close_channel = NULL, updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE id = ?1 AND status = ''closed'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status IN (''closed'',''resolved'')) THEN ''issue-reopened'' WHEN EXISTS (SELECT 1 FROM issue_triage it JOIN agent_issues s ON s.id = CAST(substr(it.close_evidence, 16) AS INTEGER) WHERE it.issue_id = ?1 AND it.close_evidence LIKE ''SUPERSEDED BY #%'') THEN ''ok'' ELSE ''successor-missing'' END AS observed', 'delegated', 3, 12, 1, 'on', 'Duplicate open issue per trigger id (the whole-title dedupe of evaluateMetricTriggers files a second issue when a trigger title is edited). Supersedes the loser to the survivor with SUPERSEDED BY #<id>. The survivor is the issue whose title is the one evaluateMetricTriggers looks up for the trigger now (the title tail equals the trigger''s current title, cur = 0), because that lookup reads lower(trim(title)) over open, monitoring AND closed and reopens a closed match (''parked twin reopened''): closing the current-title issue would flap, close then reopen, up to max_per_day times. When neither or both bear it, the higher priority and then the lower id survive. The rule acts only when the survivor is at least as urgent as the loser, because a playbook statement binds one issue and cannot raise a priority. Live 2026-10-26 (re-read after the review): 0 hits. The one hit of the first draft, the hand-filed 1000015 beside 100088 of trigger 8888, is the owner''s own note (source owner-chat, filed from the owner''s chat on 2026-10-24) and not a double filing by the evaluator: every colon-form ''METRIC-TRIGGER: <metric>'' issue ever filed has source owner-chat (2 rows, 1 open), so the rule reads only the evaluator''s METRIC-TRIGGER-<id>- titles and skips a source that begins with owner (a NULL source is not owner). The pairs of triggers 354 and 409 were closed by hand after the audit, and on their live titles the rule ranks 100226 and 100225 (current titles, cur = 0) above 99924 and 99928 (old titles, cur = 1), so it names the old-title issues and keeps the ones the evaluator looks up; seeded because the pair recurred three times in a week and the code prevention (MD-P1a) is a code-task. Revert reopens the loser.'),
 ('MD-4', 1, 'METRIC-TRIGGER', 'metric-recovered-open', 'sql', 'WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*''), cand AS (SELECT oi.issue_id AS issue_id, oi.tid AS tid, (SELECT MIN(l.fired_at) FROM analytics_action_log l WHERE l.trigger_id = oi.tid AND l.status = ''recovering'' AND l.id > COALESCE((SELECT MAX(f.id) FROM analytics_action_log f WHERE f.trigger_id = oi.tid AND f.status NOT IN (''recovering'',''recovered'')), 0)) AS streak_at FROM oi), st AS (SELECT cand.issue_id AS issue_id, cand.tid AS tid, cand.streak_at AS streak_at, s.val AS val, s.threshold AS thr FROM cand JOIN v_metric_trigger_state s ON s.id = cand.tid WHERE cand.streak_at IS NOT NULL AND (julianday(''now'') - julianday(cand.streak_at)) * 1440 >= 120 AND s.hit = 0 AND s.queue_target = ''agent_issues'') SELECT st.issue_id AS issue_id, ''recovered-open'' AS subject, json_object(''trigger_id'', st.tid, ''value'', st.val, ''threshold'', st.thr, ''clear_min'', CAST((julianday(''now'') - julianday(st.streak_at)) * 1440 AS INTEGER)) AS facts_json FROM st WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = st.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host''))', json_array('WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*''), cand AS (SELECT oi.issue_id AS issue_id, oi.tid AS tid, (SELECT MIN(l.fired_at) FROM analytics_action_log l WHERE l.trigger_id = oi.tid AND l.status = ''recovering'' AND l.id > COALESCE((SELECT MAX(f.id) FROM analytics_action_log f WHERE f.trigger_id = oi.tid AND f.status NOT IN (''recovering'',''recovered'')), 0)) AS streak_at FROM oi), st AS (SELECT cand.issue_id AS issue_id, cand.tid AS tid, cand.streak_at AS streak_at, s.val AS val, s.threshold AS thr FROM cand JOIN v_metric_trigger_state s ON s.id = cand.tid WHERE cand.streak_at IS NOT NULL AND (julianday(''now'') - julianday(cand.streak_at)) * 1440 >= 120 AND s.hit = 0 AND s.queue_target = ''agent_issues'') INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT st.issue_id, ''breach-doctor:MD-4'', ''closed'', ''breach-doctor'', datetime(''now''), ''TRIGGER-RECOVERY-1 second path: metric trigger '' || st.tid || '' reads clear, value '' || st.val || '' against threshold '' || st.thr || '', for '' || CAST((julianday(''now'') - julianday(st.streak_at)) * 1440 AS INTEGER) || '' minutes since its recovery streak opened with no relapse after it, and the evaluator had not closed issue '' || st.issue_id || ''. Closed by breach-doctor rule MD-4 from analytics_action_log and v_metric_trigger_state facts only.'' FROM st WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = st.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = st.issue_id OR xw.path = ''issue:'' || st.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND st.issue_id = ?1 ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = ''closed'', owner = ''breach-doctor'', close_evidence = excluded.close_evidence'), json_array('UPDATE issue_triage SET triage_state = ''triaged'', close_evidence = NULL WHERE issue_id = ?1', 'UPDATE agent_issues SET status = ''open'', close_channel = NULL, updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE id = ?1 AND status = ''closed'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status IN (''closed'',''resolved'')) THEN ''issue-reopened'' WHEN EXISTS (SELECT 1 FROM v_metric_trigger_state s WHERE s.id = (SELECT CAST(substr(x.title, 16, instr(substr(x.title, 16), ''-'') - 1) AS INTEGER) FROM agent_issues x WHERE x.id = ?1) AND s.hit = 1) THEN ''metric-hit-again'' ELSE ''ok'' END AS observed', 'delegated', 6, 24, 1, 'on', 'Recovered but open: the trigger reads clear, its recovery streak (the evaluator''s own ''recovering'' row after the last firing, analytics_action_log) is 120 minutes old with no relapse, and the evaluator has not closed the issue (second path of TRIGGER-RECOVERY-1 for the 06:20Z case, when 6 such issues sat open while the heartbeat was down). Closes with the reading, the threshold and the streak length as evidence. Live 2026-10-26 11:30Z: 0 hits (227 rows read): the evaluator is closing on its own again; this is the guard if it stops. Control metric-playbook-recovery-hold. Revert reopens.'),
 ('MD-6', 1, 'METRIC-TRIGGER', 'metric-covered-by-parent', 'sql', 'WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') SELECT c.issue_id AS issue_id, ''covered-by-parent'' AS subject, json_object(''child_trigger'', c.tid, ''parent_trigger'', pt.id, ''parent_issue'', MIN(pi.issue_id), ''parent_priority'', pi.pri, ''child_priority'', c.pri) AS facts_json FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = ''disabled-duplicate'' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 JOIN oi pi ON pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = c.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) GROUP BY c.issue_id', json_array('WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT c.issue_id, ''breach-doctor:MD-6'', ''closed'', ''breach-doctor'', datetime(''now''), ''SUPERSEDED BY #'' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END)) || '': metric trigger '' || c.tid || '' is disabled (enabled=0) and metric_deps relation disabled-duplicate names metric '' || d.parent_metric || '' as the one that keeps its meaning, and the trigger '' || pt.id || '' of that metric is enabled and #'' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END)) || '' is open, at least as urgent and carries the work. Closed by breach-doctor rule MD-6 from analytics_metric_triggers, metric_deps and agent_issues facts only.'' FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = ''disabled-duplicate'' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 WHERE c.issue_id = ?1 AND (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = c.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = c.issue_id OR xw.path = ''issue:'' || c.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = ''closed'', owner = ''breach-doctor'', close_evidence = excluded.close_evidence'), json_array('UPDATE issue_triage SET triage_state = ''triaged'', close_evidence = NULL WHERE issue_id = ?1', 'UPDATE agent_issues SET status = ''open'', close_channel = NULL, updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE id = ?1 AND status = ''closed'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status IN (''closed'',''resolved'')) THEN ''issue-reopened'' WHEN EXISTS (SELECT 1 FROM issue_triage it JOIN agent_issues s ON s.id = CAST(substr(it.close_evidence, 16) AS INTEGER) WHERE it.issue_id = ?1 AND it.close_evidence LIKE ''SUPERSEDED BY #%'') THEN ''ok'' ELSE ''successor-missing'' END AS observed', 'delegated', 6, 24, 1, 'on', 'Covered by parent: a METRIC-TRIGGER issue whose trigger is disabled (enabled = 0) and whose metric has an active metric_deps row (relation disabled-duplicate, seeded from the BREACH-ONE-MEANING-1 notes) naming a metric whose trigger is enabled and has an open issue that is at least as urgent. Supersedes the child to the lowest-id such issue (SUPERSEDED BY #<id>). The 0.53.0 validator binds every statement to the one issue, so the playbook cannot raise a parent: the migration raised the parents of today''s children once (backup table bak_20261026_metric_playbooks_priority) and a child more urgent than its parent stays open, urgency is never dropped. Live 2026-10-26 (1,503 rows read): 4 hits before the file raises the parents, 6 after: 3015, 99914 and 99915 are reachable by the doctor, while 99937, 2570 and 100225 carry a stale code-task line or a merged code task (ct_f1fd327k5oyfkr merged for 100225), which bdLoadState reads as a doer, so the doctor never selects them and the migration closes those three once. A numeric-check relation (sum-of, ratio-of) needs its own playbook per relation and is not seeded.');

-- ONE-TIME: raise each parent issue of a covered child to the most urgent priority among its children. bak_20261026_metric_playbooks_priority keeps the previous priorities (the Rollback restores them).
-- The playbook MD-6 then supersedes a child only into a parent at least as urgent, so no urgency is lost: 99938 becomes critical (child 100225, trigger 409, superseded into it by the next statement), 100301 high (child 99915), 99935 stays medium.
CREATE TABLE IF NOT EXISTS bak_20261026_metric_playbooks_priority AS
WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), '-') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = 'open' AND lower(trim(a.title)) >= 'metric-trigger-' AND lower(trim(a.title)) < 'metric-trigger.' AND a.title GLOB 'METRIC-TRIGGER-[0-9]*')
SELECT a.id AS id, a.priority AS priority FROM agent_issues a WHERE a.id IN (SELECT pi.issue_id FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = 'disabled-duplicate' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 JOIN oi pi ON pi.tid = pt.id AND pi.issue_id <> c.issue_id);

WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), '-') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = 'open' AND lower(trim(a.title)) >= 'metric-trigger-' AND lower(trim(a.title)) < 'metric-trigger.' AND a.title GLOB 'METRIC-TRIGGER-[0-9]*'), up AS (SELECT pi.issue_id AS pid, MIN(CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) AS crank FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = 'disabled-duplicate' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 JOIN oi pi ON pi.tid = pt.id AND pi.issue_id <> c.issue_id GROUP BY pi.issue_id)
UPDATE agent_issues SET priority = CASE (SELECT up.crank FROM up WHERE up.pid = agent_issues.id) WHEN 0 THEN 'critical' WHEN 1 THEN 'high' WHEN 2 THEN 'medium' ELSE 'low' END
WHERE status = 'open' AND id IN (SELECT pid FROM up) AND (CASE priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) > (SELECT up.crank FROM up WHERE up.pid = agent_issues.id);

-- ONE-TIME: bdLoadState reads an open issue as owned (a doer) when its description carries a code-task line, or when any code_tasks row whose goal starts with [issue #N] has a status outside failed, closed,
-- superseded and needs_human (a MERGED task counts), and bdSelect skips an owned issue. So the covered children 99937 (line, tasks ct_7i753c8gmtb38z and ct_im99937 merged 2026-10-19), 2570 (line, task ct_im2570
-- closed 2026-10-19) and 100225 (no line, task ct_f1fd327k5oyfkr merged, goal [issue #100225] METRIC-TRIGGER-409-...) can never be reached by MD-6. The same close is applied to them once, with the same evidence,
-- when the engine reads them as owned only because of a line or a task that has ended and no code task of the issue is in flight. The children the doctor does reach are 3015, 99914 and 99915 (live_ct = 0, no line).
WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), '-') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = 'open' AND lower(trim(a.title)) >= 'metric-trigger-' AND lower(trim(a.title)) < 'metric-trigger.' AND a.title GLOB 'METRIC-TRIGGER-[0-9]*') INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT c.issue_id, 'breach-doctor:MD-6:migration', 'closed', 'breach-doctor', datetime('now'), 'SUPERSEDED BY #' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END)) || ': metric trigger ' || c.tid || ' is disabled (enabled=0) and metric_deps relation disabled-duplicate names metric ' || d.parent_metric || ' as the one that keeps its meaning, and the trigger ' || pt.id || ' of that metric is enabled and #' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END)) || ' is open, at least as urgent and carries the work. Closed once by migration 2026-10-26-metric-playbooks (rule MD-6) because the engine reads the code-task line or the merged code task of this issue as a doer, and every code task of this issue has ended.' FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = 'disabled-duplicate' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 WHERE (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = c.issue_id AND xc.status IN ('active','holding') AND COALESCE(xc.last_verdict,'') IN ('fail','vacuous-probe-result','probe-error','probe-not-machine-executable','probe-same-account-host')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = c.issue_id OR xw.path = 'issue:' || c.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime('%Y-%m-%dT%H:%M:%SZ','now')) AND c.issue_id IN (SELECT a.id FROM agent_issues a WHERE a.status = 'open' AND (instr(COALESCE(a.description, ''), 'code-task:') > 0 OR EXISTS (SELECT 1 FROM code_tasks e WHERE e.goal LIKE '[issue #' || a.id || ']%' AND e.status NOT IN ('failed', 'closed', 'superseded', 'needs_human'))) AND NOT EXISTS (SELECT 1 FROM code_tasks k WHERE (k.goal LIKE '[issue #' || a.id || ']%' OR k.id = 'ct_im' || a.id) AND k.status NOT IN ('merged', 'failed', 'closed', 'superseded', 'needs_human', 'publish_failed'))) ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = 'closed', owner = 'breach-doctor', close_evidence = excluded.close_evidence;

-- ONE-TIME: issue 99949 (trigger 5916 papers_live_failing_release_gate) is also stranded: the trigger is disabled and has no parent metric (BREACH-ONE-MEANING-1: it contradicts the owner directive of 2026-10-26 06:35,
-- pub-gate-v4-no-withdraw, a weak paper stays live and is revised), and its two code tasks merged on 2026-10-19 and 2026-10-20. The evaluator never reopens the issue of a disabled trigger. Closed with MOOT evidence.
INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence)
SELECT a.id, 'breach-doctor:MD-6:migration', 'closed', 'breach-doctor', datetime('now'),
  'MOOT: metric trigger 5916 (papers_live_failing_release_gate) is disabled (enabled=0) and no metric carries its meaning in metric_deps; BREACH-ONE-MEANING-1 disabled it on 2026-10-26 because it contradicts the owner directive of 2026-10-26 06:35 (pub-gate-v4-no-withdraw: a weak paper stays live and is revised), its code tasks ct_cl1domo3wy60p9 and ct_im99949 merged on 2026-10-19 and 2026-10-20, and the evaluator never reopens the issue of a disabled trigger. Closed once by migration 2026-10-26-metric-playbooks from analytics_metric_triggers and code_tasks facts only.'
FROM agent_issues a
WHERE a.id = 99949 AND a.status = 'open' AND a.title LIKE 'METRIC-TRIGGER-5916-%'
  AND EXISTS (SELECT 1 FROM analytics_metric_triggers t WHERE t.id = 5916 AND t.enabled = 0)
  AND NOT EXISTS (SELECT 1 FROM code_tasks k WHERE k.goal LIKE '[issue #99949]%' AND k.status NOT IN ('merged', 'failed', 'closed', 'superseded', 'needs_human', 'publish_failed'))
  AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = a.id AND xc.status IN ('active','holding') AND COALESCE(xc.last_verdict,'') IN ('fail','vacuous-probe-result','probe-error','probe-not-machine-executable','probe-same-account-host')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = a.id OR xw.path = 'issue:' || a.id) AND xw.released_at IS NULL AND xw.expires_at > strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = 'closed', owner = 'breach-doctor', close_evidence = excluded.close_evidence;

-- Code levers (ACT-BRIDGE-1): one change each in qnfo-fleet-control/worker.js, a file the code loop may change (CODE-LOOP-CONTROL-PLANE-1). The code-anchor of each lever occurs exactly once in that file on main
-- (read 2026-10-26, count 1 each); its code-probe fails today and passes only when the edit is on main, and that code-read contract is the issue's closing probe.
-- A d1 outcome contract is added only where it FAILS while the defect exists and is gated on the code-read contract's own passing verification (MD-P1c):
-- the live trigger remediation_verification_autoclose_ins closes an issue when a pass lands and no other active contract has a failing latest verification, and a contract with no verification yet does not block it, so
-- an outcome that already reads ok at birth would close the issue before any code change. MD-P1a and MD-P1b have no symptom to measure today (0 duplicate pairs, 0 odd operators), so they carry the code-probe alone.
-- THE DOER OF EACH LEVER IS A CODE TASK THIS FILE QUEUES (last statement of the levers below), because intake would refuse every one. qnfo-code-orchestrator intakeIssues calls intakePreflight, whose issueKey(title) is
-- 'BREACH-DOCTOR-1' for every title with the family prefix (the trusted pair qnfo-fleet-control|BREACH-DOCTOR-1: forces that prefix), and it refuses an issue whose key is in fleet_changelog within 72 hours ('its key shipped ... so
-- the fix is probably on main already') and rewrites its 'code-task: repo=' line to 'session-task: repo=' for good. qnfo-fleet-control 0.52.0-breach-doctor released the key on 2026-10-26T10:21:17Z, so intake refuses until
-- 2026-10-29T10:21Z at the earliest, and the red-drain dispatch is no route either (its step 3 skips every issue that names path=qnfo-fleet-control/). The task is inserted the way that dispatch inserts one: id ct_im<issue>
-- (INTAKE-IM-DEDUPE-1 reads it as the issue's task, the PARKED-TASK-ISSUE-CLOSED-1 trigger links it), goal prefix [issue #N] (the merge runner reads the issue's source and title from it, cmProvenance, and the queue_pulls trigger
-- records the pull) and the issue's code-anchor in ctx, the shape enqueue() writes. intakeIssues then finds the task in flight and builds no second one. Exempting the family prefix, which is not a release key, from issueKey is a
-- change to qnfo-code-orchestrator for all BREACH-DOCTOR-1 packages and is not made in this data file.
-- Single-row VALUES inserts: agent_issues refuses the INSERT ... SELECT shape at compile time on some days (migrations/2026-10-18-issue-sla-guard-reliable.sql); agent_issues_open_dup_annotate makes a replay a no-op.


INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P1a qnfo-fleet-control evaluateMetricTriggers dedupes a trigger issue by trigger id, not by the whole title',
  'Charter pillar: autonomy (ACT-BRIDGE-1, BREACH-DOCTOR-1 rule MD-1). evaluateMetricTriggers files METRIC-TRIGGER-<id>-<METRIC>: <title> and looks for an existing issue by the whole title, so a trigger whose title is edited files a second open issue for the same trigger: COST-BUDGET-RECALIBRATION-1 did it to triggers 354 and 409 (two pairs open on 2026-10-26 06:35Z: 99924/100226, 99928/100225). The playbook MD-1 closes the extra issue, keeping the one whose title is the evaluator''s current one (a closed twin of the current title is reopened by the evaluator); this change stops the second issue being filed.' || char(10) ||
  'Edit: in qnfo-fleet-control/worker.js evaluateMetricTriggers replace the lookup on the line after the var title line (SELECT id, status FROM agent_issues WHERE lower(trim(title)) = lower(trim(?1)) AND status IN (''open'',''monitoring'',''closed'') ORDER BY CASE status ...) with a lookup by trigger id: SELECT id, status FROM agent_issues WHERE title LIKE ?1 AND status IN (''open'',''monitoring'',''closed'') ORDER BY CASE status WHEN ''open'' THEN 0 WHEN ''monitoring'' THEN 1 ELSE 2 END, id LIMIT 1, bound to "METRIC-TRIGGER-" + t.id + "-%". Keep the title that is inserted, the reopen branch of a parked twin, the deduped note and the unreadable list as they are. Test: a trigger whose title changes between two ticks files one issue, and its reopen still finds the closed twin.' || char(10) ||
  'Definition of done: the old whole-title lookup is gone from main. The code-probe below is the closing probe of this issue and the only contract it carries: the symptom check (no trigger id has two open issues) reads ok today, held at 0 by hand and by MD-1, so it cannot gate a close and is not a contract.' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
  'code-anchor: var title = "METRIC-TRIGGER-" + t.id + "-" + String(t.metric_key).toUpperCase().replace(/[^A-Z0-9]+/g, "-") + ": " + String(t.title || t.action || "").slice(0, 80);' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "absent": "lower(trim(title)) = lower(trim(?1)) AND status IN (''open'',''monitoring'',''closed'')"}',
  'qnfo-fleet-control', 'reliability', 'medium', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);


INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P1b qnfo-fleet-control an operator outside gt, gte, lt, lte, eq is unreadable, never read as gte',
  'Charter pillar: autonomy (ACT-BRIDGE-1, BREACH-DOCTOR-1 rule MD-2). evaluateMetricTriggers, ilTriggerHit and perfBreaches read every operator they do not know as gte. A trigger written with ''>'' therefore fired at value 0 against threshold 0 (prd_funnel_monitor_stale and personal_calendar_delivery_over_120m were false breaches until BREACH-ONE-MEANING-1 normalised the symbols in D1 with two triggers and a view); a typo or a new symbol would do it again, in code, where nothing normalises it.' || char(10) ||
  'Edit: in qnfo-fleet-control/worker.js make the comparison fail closed in all three places that carry the line ... op === "eq" ? v === thr : v >= thr: accept gt, gte, lt, lte, eq and the symbols > >= < <= = ==; a missing or empty operator keeps meaning gte; any other operator in evaluateMetricTriggers pushes t.metric_key to out.unreadable and continues, and in ilTriggerHit and perfBreaches returns false. Every known operator keeps its exact behaviour. Test: operator ''!='' with value 5 and threshold 1 is unreadable and files nothing; ''>'' with value 0 and threshold 0 is not a hit.' || char(10) ||
  'Definition of done: no comparison on main ends in op === "eq" ? v === thr : v >= thr. The code-probe below is the closing probe of this issue and the only contract it carries: the symptom check (no enabled trigger has an operator outside the set) reads ok today because BREACH-ONE-MEANING-1 normalises the symbols in D1, so it cannot gate a close and is not a contract.' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
  'code-anchor: var hit = op === "gt" ? v > thr : op === "lte" ? v <= thr : op === "lt" ? v < thr : op === "eq" ? v === thr : v >= thr;' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "absent": ": op === \"eq\" ? v === thr : v >= thr;"}',
  'qnfo-fleet-control', 'reliability', 'medium', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);


INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P1c qnfo-fleet-control a recovered trigger issue closes after 3 refresh cadences (at most 120 minutes), not after a fixed 60',
  'Charter pillar: autonomy (ACT-BRIDGE-1, BREACH-DOCTOR-1 rule MD-4). TRIGGER-RECOVERY-1 closes a METRIC-TRIGGER issue once its metric has been clear for TRIGGER_RECOVERY_MIN = 60 minutes, and the next hit reopens the closed twin. Measured 2026-10-26 on issue_lifecycle for METRIC-TRIGGER issues: 166 reopened events in 7 days and 57 in the last 24 h. Of the 166, 36 came within 60 minutes of the preceding close, 10 within 60 to 120 minutes, 118 later and 2 had no close; of the 57 in the last 24 h, 26 came within 60 minutes. A hold of 120 minutes instead of 60 withholds the closes that a relapse inside the second clear hour followed (36 of 166, 22 percent of the churn). The 10 that reopened 60 to 120 minutes after a close at 60 minutes close at 120 minutes now and reopen within the hour after it, so the under-60 band keeps about 10 a week (1.4 a day). The longer hold of the audit (6 h, 24 h) would keep recovered issues open past 120 minutes (SLA-120M-1, ISSUE-SLA-2H-1), so the hold is capped at 120.' || char(10) ||
  'Edit: in qnfo-fleet-control/worker.js keep var TRIGGER_RECOVERY_MIN = 60 as the floor and add var TRIGGER_RECOVERY_MAX_MIN = 120 and a pure helper triggerRecoveryHoldMin(refreshCadence) that returns Math.min(TRIGGER_RECOVERY_MAX_MIN, Math.max(TRIGGER_RECOVERY_MIN, 3 x the cadence in minutes)) with the cadence read from metric_registry.refresh_cadence (''10m'' or ''*/10'' 10, ''1h'' or ''hourly'' 60, ''2h'' 120, anything else 60). Use it in the triggerRecoveryDue(streak.t, Date.now(), ...) call of the recovery branch, reading the cadence of t.metric_key once per trigger. A hit during the streak still writes relapsed and ends it. Test: an hourly metric clear for 90 minutes is not closed, at 125 it is; a 10-minute metric closes at 60.' || char(10) ||
  'Definition of done: TRIGGER_RECOVERY_MAX_MIN exists on main (the code-probe, this issue''s code-read contract) and, once it is deployed, at most 5 METRIC-TRIGGER closes were reopened within 60 minutes of the close in the last 24 h (the d1 contract issue-<id>-outcome, which reads a reason until the code-read contract has a passing verification; 26 today, about 1.4 a day expected from the 10 above). The outcome counts what the lever changes, not all reopens: the 118 later ones are not avoided by a longer hold.' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
  'code-anchor: var TRIGGER_RECOVERY_MIN = 60;' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "contains": "TRIGGER_RECOVERY_MAX_MIN"}',
  'qnfo-fleet-control', 'reliability', 'medium', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);




-- The issue-birth trigger gives each row a needs-machine-probe contract; the UPDATE sets the probe the remediation tick runs (code-probe line, PROBE-BIRTH-2), the INSERT OR IGNORE gives a replay and the offline suite the same rows.
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id, id, 'born with the issue (ORPHAN-GUARD-BIRTH-1)', 'needs-machine-probe', 'needs-machine-probe', 'd1-query', 3, 'qnfo-fleet-control', 1, 'needs-machine-probe', 'birth'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P%' AND status = 'open';


UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main, scripts/remediation_consumer.py reads its checkout of main and a pass is the closing probe of the code part of the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "absent": "lower(trim(title)) = lower(trim(?1)) AND status IN (''open'',''monitoring'',''closed'')"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1a %' ORDER BY id DESC LIMIT 1);


UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main, scripts/remediation_consumer.py reads its checkout of main and a pass is the closing probe of the code part of the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "absent": ": op === \"eq\" ? v === thr : v >= thr;"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1b %' ORDER BY id DESC LIMIT 1);


UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main, scripts/remediation_consumer.py reads its checkout of main and a pass is the closing probe of the code part of the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "contains": "TRIGGER_RECOVERY_MAX_MIN"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1c %' ORDER BY id DESC LIMIT 1);

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id || '-outcome', id, 'METRIC-PLAYBOOKS-1: the outcome the edit is for, gated on the code part', 'the edit lands and the measured outcome holds', 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM remediation_verifications v WHERE v.class = ''issue-' || id || ''' AND v.pass = 1) THEN ''the code part of this issue has no passing verification yet'' WHEN (SELECT COUNT(*) FROM issue_lifecycle l JOIN agent_issues a ON a.id = l.issue_id WHERE l.event = ''reopened'' AND l.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'') AND a.title LIKE ''METRIC-TRIGGER-%'' AND EXISTS (SELECT 1 FROM issue_lifecycle c WHERE c.id = (SELECT MAX(c2.id) FROM issue_lifecycle c2 WHERE c2.issue_id = l.issue_id AND c2.id < l.id AND c2.to_status IN (''closed'', ''resolved'')) AND c.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', l.ts, ''-60 minutes''))) > 5 THEN ''more than 5 METRIC-TRIGGER closes were reopened within 60 minutes of the close in 24 hours'' ELSE ''ok'' END AS observed', 'd1-query', 1000, 'qnfo-fleet-control', 1, 'active', 'metric-playbooks'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1c %' AND status = 'open' ORDER BY id DESC LIMIT 1;

-- The fleet doer of each lever (see the note above the levers): one queued code task per lever issue, id ct_im<issue>, goal '[issue #N] <title>' plus the issue text without its code-task line, ctx = the code-anchor line.
-- A replay inserts nothing: the primary key is the id, and the NOT EXISTS reads any task of the issue.
WITH l AS (SELECT a.id AS id, a.title AS title, a.description AS d, instr(a.description, 'code-task: repo=') AS ct, substr(a.description, instr(a.description, 'code-anchor: ') + 13) AS rest FROM agent_issues a WHERE a.status = 'open' AND a.title LIKE 'BREACH-DOCTOR-1: MD-P1_ %' AND instr(a.description, 'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js') > 0 AND instr(a.description, 'code-anchor: ') > 0),
 g AS (SELECT l.id AS id, l.title AS title, substr(l.d, 1, l.ct - 1) AS pre, substr(substr(l.d, l.ct), instr(substr(l.d, l.ct), char(10)) + 1) AS post, CASE WHEN instr(l.rest, char(10)) > 0 THEN substr(l.rest, 1, instr(l.rest, char(10)) - 1) ELSE l.rest END AS anchor FROM l)
INSERT OR IGNORE INTO code_tasks (id, repo, path, goal, status, step, attempts, ctx, created_at, updated_at)
SELECT 'ct_im' || g.id, 'qnfo-workers', 'qnfo-fleet-control/worker.js', '[issue #' || g.id || '] ' || substr(g.title, 1, 200) || char(10) || substr(g.pre || g.post, 1, 5600), 'queued', 'read', 0, json_object('anchor', g.anchor), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM g WHERE NOT EXISTS (SELECT 1 FROM code_tasks k WHERE k.id = 'ct_im' || g.id OR k.goal LIKE '[issue #' || g.id || ']%');




