 ('fm-metric-trigger-disabled-issue-open', NULL, 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') oi JOIN analytics_metric_triggers t ON t.id = oi.tid AND t.enabled = 0 JOIN agent_issues a ON a.id = oi.issue_id WHERE a.created_at < (CAST(strftime(''%s'',''now'') AS INTEGER) - 7200) * 1000 AND EXISTS (SELECT 1 FROM breach_playbooks p WHERE p.rule_id = ''MD-6'' AND p.created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-90 minutes''))) AS TEXT) AS observed', 'd1-query', 3, 1, 'active', 'METRIC-PLAYBOOKS-1', 'failure-mode detector', 'qnfo-fleet-control', 'failure-mode');

